export function createButton(root) {
  const status = root.querySelector('[data-button-status]');

  if (!(status instanceof HTMLElement)) {
    throw new Error('Button demo markup is incomplete.');
  }

  const handleClick = (event) => {
    const button = event.target.closest('[data-button-action]');
    if (!(button instanceof HTMLButtonElement) || !root.contains(button)) return;

    const action = button.dataset.buttonAction || button.textContent.trim();
    status.textContent = `${action} activated.`;
    root.dispatchEvent(new CustomEvent('button:activate', {
      detail: { action }
    }));
  };

  root.addEventListener('click', handleClick);

  return {
    destroy() {
      root.removeEventListener('click', handleClick);
    }
  };
}

document.querySelectorAll('[data-component="button"]').forEach(createButton);

