export function createToggleButtons(root) {
  const status = root.querySelector('[data-toggle-status]');
  if (!(status instanceof HTMLElement)) throw new Error('Toggle button markup is incomplete.');

  const getButtons = (group) => [...group.querySelectorAll('[data-toggle-value]')].filter((button) => button instanceof HTMLButtonElement && !button.disabled);
  const setTabStop = (group, active) => {
    getButtons(group).forEach((button) => { button.tabIndex = button === active ? 0 : -1; });
  };
  const handleClick = (event) => {
    if (!(event.target instanceof Element)) return;
    const button = event.target.closest('[data-toggle-value]');
    if (!(button instanceof HTMLButtonElement) || button.disabled || !root.contains(button)) return;
    const group = button.closest('[data-toggle-group]');
    if (!(group instanceof HTMLElement)) return;
    const pressed = button.getAttribute('aria-pressed') === 'true';
    if (group.dataset.toggleGroup === 'exclusive') {
      getButtons(group).forEach((item) => item.setAttribute('aria-pressed', 'false'));
    }
    button.setAttribute('aria-pressed', String(!pressed));
    status.textContent = `${button.getAttribute('aria-label')} ${pressed ? 'off' : 'on'}.`;
  };
  const handleFocus = (event) => {
    if (!(event.target instanceof HTMLButtonElement)) return;
    const group = event.target.closest('[data-toggle-group]');
    if (group instanceof HTMLElement && root.contains(group)) setTabStop(group, event.target);
  };
  const handleKeydown = (event) => {
    if (!(event.target instanceof HTMLButtonElement)) return;
    const group = event.target.closest('[data-toggle-group]');
    if (!(group instanceof HTMLElement) || !root.contains(group)) return;
    const buttons = getButtons(group);
    const index = buttons.indexOf(event.target);
    if (index < 0) return;
    let next;
    if (event.key === 'ArrowRight') next = buttons[(index + 1) % buttons.length];
    else if (event.key === 'ArrowLeft') next = buttons[(index - 1 + buttons.length) % buttons.length];
    else if (event.key === 'Home') next = buttons[0];
    else if (event.key === 'End') next = buttons[buttons.length - 1];
    else return;
    event.preventDefault();
    next.focus();
  };

  root.addEventListener('click', handleClick);
  root.addEventListener('focusin', handleFocus);
  root.addEventListener('keydown', handleKeydown);
  return { destroy() {
    root.removeEventListener('click', handleClick);
    root.removeEventListener('focusin', handleFocus);
    root.removeEventListener('keydown', handleKeydown);
  } };
}

document.querySelectorAll('[data-component="toggle-buttons"]').forEach(createToggleButtons);

