export function createToggleButtons(root: Element): { destroy(): void } {
  const status = root.querySelector<HTMLElement>('[data-toggle-status]');
  if (!status) throw new Error('Toggle button markup is incomplete.');

  const getButtons = (group: Element): HTMLButtonElement[] =>
    Array.from(group.querySelectorAll<HTMLButtonElement>('[data-toggle-value]')).filter((button) => !button.disabled);
  const setTabStop = (group: Element, active: HTMLButtonElement): void => {
    getButtons(group).forEach((button) => { button.tabIndex = button === active ? 0 : -1; });
  };
  const handleClick = (event: Event): void => {
    if (!(event.target instanceof Element)) return;
    const button = event.target.closest<HTMLButtonElement>('[data-toggle-value]');
    if (!button || button.disabled || !root.contains(button)) return;
    const group = button.closest<HTMLElement>('[data-toggle-group]');
    if (!group) return;
    const pressed = button.getAttribute('aria-pressed') === 'true';
    if (group.dataset['toggleGroup'] === 'exclusive') {
      getButtons(group).forEach((item) => item.setAttribute('aria-pressed', 'false'));
    }
    button.setAttribute('aria-pressed', String(!pressed));
    status.textContent = `${button.getAttribute('aria-label')} ${pressed ? 'off' : 'on'}.`;
  };
  const handleFocus = (event: Event): void => {
    if (!(event.target instanceof HTMLButtonElement)) return;
    const group = event.target.closest<HTMLElement>('[data-toggle-group]');
    if (group && root.contains(group)) setTabStop(group, event.target);
  };
  const handleKeydown = (event: Event): void => {
    if (!(event instanceof KeyboardEvent) || !(event.target instanceof HTMLButtonElement)) return;
    const group = event.target.closest<HTMLElement>('[data-toggle-group]');
    if (!group || !root.contains(group)) return;
    const buttons = getButtons(group);
    const index = buttons.indexOf(event.target);
    if (index < 0) return;
    let next: HTMLButtonElement;
    if (event.key === 'ArrowRight') next = buttons[(index + 1) % buttons.length];
    else if (event.key === 'ArrowLeft') next = buttons[(index - 1 + buttons.length) % buttons.length];
    else if (event.key === 'Home') next = buttons[0];
    else if (event.key === 'End') next = buttons[buttons.length - 1];
    else return;
    event.preventDefault();
    next.focus();
  };

  root.addEventListener('click', handleClick);
  root.addEventListener('focusin', handleFocus);
  root.addEventListener('keydown', handleKeydown);
  return { destroy(): void {
    root.removeEventListener('click', handleClick);
    root.removeEventListener('focusin', handleFocus);
    root.removeEventListener('keydown', handleKeydown);
  } };
}

document.querySelectorAll<HTMLElement>('[data-component="toggle-buttons"]').forEach(createToggleButtons);
